package main

import "fmt"

func describe(x any) string {
	switch v := x.(type) {        // v takes each case's concrete type
	case int:
		return fmt.Sprintf("int: %d", v*2)      // v is an int here
	case string:
		return fmt.Sprintf("string of len %d", len(v)) // v is a string
	case float64:
		return fmt.Sprintf("float: %.1f", v)
	default:
		return fmt.Sprintf("other: %v (%T)", v, v)   // %T prints the type
	}
}

func main() {
	for _, v := range []any{42, "hi", 3.14, true} {
		fmt.Println(describe(v))
	}
}

